object Iselect {
  def isInAIA(iselect: UInt): Bool = iselect >= 0x30.U && iselect <= 0x3f.U
  def isInImsic(iselect: UInt): Bool = iselect >= 0x70.U && iselect <= 0xff.U
  def isInOthers(iselect: UInt): Bool = !(isInAIA(iselect) || isInImsic(iselect))
}

